export function createLedger({ expectedAmounts = {} } = {}) {
  const events = new Map();
  const references = new Map();

  function handle(event) {
    if (!event || !event.type) {
      return { applied: false, reason: "unknown-type", status: null };
    }

    if (events.has(event.id)) {
      return { applied: false, reason: "duplicate", status: references.get(event.reference)?.status || null };
    }

    events.set(event.id, true);

    if (event.type !== "charge.success" && event.type !== "charge.failed" && event.type !== "charge.abandoned" && event.type !== "refund.processed") {
      return { applied: false, reason: "unknown-type", status: null };
    }

    if (event.type === "charge.success" || event.type === "refund.processed") {
      if (event.amountKobo <= 0 || !Number.isInteger(event.amountKobo)) {
        return { applied: false, reason: "invalid-amount", status: references.get(event.reference)?.status || null };
      }
    }

    if (!references.has(event.reference)) {
      references.set(event.reference, {
        reference: event.reference,
        status: "pending",
        amountKobo: expectedAmounts[event.reference] || null,
        refundedKobo: 0,
        deferredRefunds: []
      });
    }

    const { reference, status, amountKobo, refundedKobo, deferredRefunds } = references.get(event.reference);

    if (status === "success" || status === "partially_refunded" || status === "refunded" || status === "amount_mismatch") {
      return { applied: false, reason: "terminal", status };
    }

    if (event.type === "charge.failed") {
      if (status === "pending" || status === "abandoned") {
        references.set(event.reference, { ...references.get(event.reference), status: "failed" });
        return { applied: true, reason: null, status: "failed" };
      } else {
        return { applied: false, reason: "stale", status };
      }
    }

    if (event.type === "charge.abandoned") {
      if (status === "pending") {
        references.set(event.reference, { ...references.get(event.reference), status: "abandoned" });
        return { applied: true, reason: null, status: "abandoned" };
      } else {
        return { applied: false, reason: "stale", status };
      }
    }

    if (event.type === "charge.success") {
      if (expectedAmounts[reference] && event.amountKobo !== expectedAmounts[reference]) {
        references.set(event.reference, { ...references.get(event.reference), status: "amount_mismatch" });
        return { applied: true, reason: "amount-mismatch", status: "amount_mismatch" };
      } else {
        references.set(event.reference, { ...references.get(event.reference), status: "success", amountKobo: event.amountKobo });
        applyDeferredRefunds(reference);
        return { applied: true, reason: null, status: references.get(event.reference).status };
      }
    }

    if (event.type === "refund.processed") {
      if (status === "success" || status === "partially_refunded") {
        if (refundedKobo + event.amountKobo > amountKobo) {
          return { applied: false, reason: "over-refund", status };
        } else {
          references.set(event.reference, { ...references.get(event.reference), refundedKobo: refundedKobo + event.amountKobo });
          if (refundedKobo + event.amountKobo === amountKobo) {
            references.set(event.reference, { ...references.get(event.reference), status: "refunded" });
          }
          return { applied: true, reason: null, status: references.get(event.reference).status };
        }
      } else if (status === "refunded") {
        return { applied: false, reason: "over-refund", status };
      } else if (status === "pending" || status === "abandoned" || status === "failed") {
        deferredRefunds.push(event.amountKobo);
        return { applied: false, reason: "deferred", status };
      } else if (status === "amount_mismatch") {
        return { applied: false, reason: "terminal", status };
      }
    }

    return { applied: false, reason: "unknown-type", status: null };
  }

  function applyDeferredRefunds(reference) {
    const { deferredRefunds } = references.get(reference);
    for (const amount of deferredRefunds) {
      const { status, refundedKobo } = references.get(reference);
      if (status === "success" || status === "partially_refunded") {
        if (refundedKobo + amount > amountKobo) {
          break;
        } else {
          references.set(reference, { ...references.get(reference), refundedKobo: refundedKobo + amount });
          if (refundedKobo + amount === amountKobo) {
            references.set(reference, { ...references.get(reference), status: "refunded" });
          }
        }
      }
    }
  }

  function get(reference) {
    return references.get(reference);
  }

  return { handle, get };
}
